import { prisma } from '../db.js';
import type { ViewerId } from '../types.js';

/**
 * viewerId가 팔로우 중인 사용자 id 집합. viewerId가 null이면 빈 Set.
 * 글/댓글 목록에서 author.following을 N+1 쿼리 없이 계산하기 위한 헬퍼.
 */
export async function followedIdsOf(viewerId: ViewerId): Promise<Set<number>> {
  if (viewerId === null) return new Set();

  const rows = await prisma.follow.findMany({
    where: { followerId: viewerId },
    select: { followedId: true },
  });
  return new Set(rows.map((r) => r.followedId));
}

/** 단일 대상에 대한 팔로우 여부. 익명(viewerId null)이면 항상 false. */
export async function isFollowing(viewerId: ViewerId, followedId: number): Promise<boolean> {
  if (viewerId === null) return false;

  const row = await prisma.follow.findUnique({
    where: { followerId_followedId: { followerId: viewerId, followedId } },
    select: { followerId: true },
  });
  return row !== null;
}

